$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\public_sources.py"
$testPath = Join-Path $pkg "tests\test_public_sources.py"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $modulePath)) { throw "public_sources.py not found." }
if (-not (Test-Path $python)) { throw "Python venv not found: $python" }

Copy-Item $modulePath "$modulePath.bak" -Force
Copy-Item $testPath "$testPath.bak" -Force

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

Write-Host "=== REMOTE OK SOURCE FIX ==="
Write-Host "Replacing failing Remote OK RSS with the public JSON API."
Write-Host "Running full AHOS tests (NO real network and NO OpenAI API calls)..."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}

if ($testExit -ne 0) {
    Copy-Item "$modulePath.bak" $modulePath -Force
    Copy-Item "$testPath.bak" $testPath -Force
    throw "Tests failed; previous source configuration restored."
}

Remove-Item "$modulePath.bak" -Force
Remove-Item "$testPath.bak" -Force

git -C $ws add ahos_core/ahos/public_sources.py ahos_core/tests/test_public_sources.py
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "fix(ahos): use Remote OK public JSON API"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== REMOTE OK FIX COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Remote OK source: https://remoteok.com/api"
Write-Host "Git push: PASS"
Write-Host "Real network calls during fix: 0"
Write-Host "OpenAI API calls: 0"
